import { Component, Element, Event, EventEmitter, Host, Listen, Prop, h } from '@stencil/core';

/**
 * @slot default - default slot for the content of the select-option
 * @slot description - optional slot for the description below the main content
 */
@Component({
  tag: 'groupui-select-option',
  styleUrl: 'select-option.scss',
  shadow: true,
})
export class SelectOption {
  /**
   * value of the select-option to identify which option is selected.
   */
  @Prop({ reflect: true }) readonly value: string = Math.random().toString(36).substring(7);

  /**
   * marks this option as disabled, so it is shown in the select but is not selectable.
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * use this only with a searchable select, hides the option
   */
  @Prop({ reflect: true }) readonly invisible: boolean = false;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * dispatched custom event when component is selected
   */
  @Event({ bubbles: false }) groupuiOptionSelected: EventEmitter<string>;

  @Element() host: HTMLElement;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  @Listen('click', { capture: true })
  captureClick(event) {
    event.stopPropagation();

    if (!this.disabled) {
      this.groupuiOptionSelected.emit(this.value);
    }
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  render() {
    return (
      <Host tabindex={-1} role="option">
        <div id="container">
          <slot />
          {this.isDescriptionSlotProvided() && <slot name="description" />}
        </div>
      </Host>
    );
  }
}
